package org.roadwatch.api;
import org.roadwatch.model.Models.*;import org.roadwatch.repo.*;import org.roadwatch.service.ReportService;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@RestController @RequestMapping("/api") public class ApiController{
 private final ReportService service;private final ReportRepository reports;private final IssueRepository issues;private final AuditRepository audits;@Value("${roadwatch.admin-api-key}")String adminKey;
 public ApiController(ReportService s,ReportRepository r,IssueRepository i,AuditRepository a){service=s;reports=r;issues=i;audits=a;}
 @PostMapping("/reports") public RoadReport create(@RequestParam("image")MultipartFile image,@RequestParam(required=false)Double latitude,@RequestParam(required=false)Double longitude,@RequestParam(required=false)String note)throws Exception{if((latitude==null)!=(longitude==null))throw new IllegalArgumentException("Provide both latitude and longitude, or neither");if(latitude!=null&&(Math.abs(latitude)>90||Math.abs(longitude)>180))throw new IllegalArgumentException("Coordinates are out of range");return service.create(image,latitude,longitude,note);}
 @GetMapping("/admin/reports")public List<RoadReport> list(@RequestHeader(value="X-Admin-Key",required=false)String key){check(key);return reports.findAllByOrderByCreatedAtDesc();}
 @GetMapping("/map/reports")public List<RoadReport> accepted(){return reports.findByStatusOrderByCreatedAtDesc(ReportStatus.ACCEPTED).stream().filter(r->r.latitude!=null&&r.longitude!=null).toList();}
 @GetMapping("/admin/issues")public List<RoadIssue> adminIssues(@RequestHeader(value="X-Admin-Key",required=false)String key){check(key);return issues.findAllByOrderByUpdatedAtDesc();}
 @GetMapping("/admin/stats")public Map<String,Object> stats(@RequestHeader(value="X-Admin-Key",required=false)String key){check(key);List<RoadReport> all=reports.findAll();return Map.of("totalReports",all.size(),"accepted",all.stream().filter(x->x.status==ReportStatus.ACCEPTED).count(),"underReview",all.stream().filter(x->x.status==ReportStatus.UNDER_REVIEW).count(),"groupedIssues",issues.count());}
 @PatchMapping("/admin/reports/{id}/status")public RoadReport status(@PathVariable Long id,@RequestHeader(value="X-Admin-Key",required=false)String key,@RequestBody Map<String,String> body){check(key);return service.setStatus(id,ReportStatus.valueOf(body.get("status")));}
 @GetMapping("/admin/reports/{id}/audit")public List<AuditEvent> audit(@PathVariable Long id,@RequestHeader(value="X-Admin-Key",required=false)String key){check(key);return audits.findByReportIdOrderByCreatedAtAsc(id);}
 private void check(String key){if(key==null||!java.security.MessageDigest.isEqual(key.getBytes(),adminKey.getBytes()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN,"Admin key required");}
}
